   "orig": "Έλληνας επισκέπτης στο Παρίσι περιγράφει στο ΕΡΤnews τις αναταραχές: «Δεν περιορίζονταν σε ένα σημείο, ήταν σε όλη την πόλη – Αυτό με τρόμαξε»",
