   "lead": "Le autorità indiane hanno arrestato diverse persone in seguito a una mortale calca avvenuta a Calcutta durante i festeggiamenti del Durga Puja, promettendo un'azione severa. L'episodio ha gettato un'ombra sulle celebrazioni religiose nella città orientale dell'India. Lo riferisce Deutsche Welle.",
   "more": [
    "Il Durga Puja è una delle festività religiose più importanti dell'India orientale, in particolare nel Bengala Occidentale, e attira enormi folle nei templi e nelle processioni, condizioni che aumentano il rischio di incidenti da calca."
   ],
