   "lead": "Il presidente egiziano Abdel Fattah al-Sisi ha dichiarato che il suo paese è pronto a difendere l'Arabia Saudita \"se richiesto\", in un contesto di crescenti attacchi degli Houthi nella regione. Le dichiarazioni arrivano mentre le tensioni militari nello Yemen e nel Mar Rosso continuano a preoccupare i paesi del Golfo. Lo riferisce Deutsche Welle.",
