   "id": "zec34bf42",
   "sez": "spazio",
   "titolo": "Nuovo studio svela come i lunghi soggiorni nello spazio modificano il genoma umano",
   "orig": "New Research Reveals How Long Stays in Space Affects the Human Genome",
   "lead": "Un nuovo studio pubblicato su Science Advances analizza come l'esposizione prolungata alla microgravità influisca sul genoma umano, offrendo risposte a domande urgenti sugli effetti delle missioni spaziali di lunga durata sugli astronauti. La ricerca è stata condotta da un team con base a Vancouver. Lo studio approfondisce i meccanismi biologici coinvolti nei cambiamenti osservati durante le permanenze in orbita, un tema cruciale per la pianificazione di future missioni verso la Luna e Marte. Lo riferisce Universe Today.",
   "more": [
    "Le missioni spaziali di lunga durata, come quelle sulla Stazione Spaziale Internazionale, sottopongono il corpo umano a radiazioni e assenza di gravità che possono alterare l'espressione genica, la densità ossea e il sistema immunitario. Comprendere questi effetti è fondamentale per proteggere la salute degli astronauti in vista di viaggi futuri verso Marte."
   ],
