   "titolo": "Un adulto su tre in Pakistan convive con un disturbo psicologico, rivela uno studio",
   "orig": "One in three adults in Pakistan lives with psychological disorder: study",
   "lead": "Il primo sondaggio nazionale sulla salute mentale in Pakistan ha rivelato che quasi un adulto su tre vive con un disturbo mentale o comportamentale diagnosticabile, un dato che evidenzia una grave sfida di sanità pubblica per milioni di persone nel Paese. La ricerca, durata cinque anni, è la più ampia e completa mai condotta in Pakistan sul tema ed è stata realizzata da ricercatori della Pakistan Psychiatric Society. I risultati sono stati pubblicati sul British Medical Journal. Lo riferisce Dawn.",
   "more": [
    "I disturbi mentali restano spesso sottodiagnosticati nei paesi a basso e medio reddito per mancanza di risorse, stigma sociale e scarsa disponibilità di specialisti. Un dato così alto suggerisce la necessità di investimenti pubblici in prevenzione, assistenza psichiatrica di base e sensibilizzazione, per evitare che il problema resti sommerso e aggravi il carico sanitario complessivo del Paese."
   ],
