   "sez": "mondo",
   "titolo": "Attacchi a navi cisterna al largo degli Emirati e dello Yemen, droni abbattuti vicino Riyadh",
   "orig": "Iran war live: Ships attacked off UAE, Yemen; drones downed near Riyadh",
   "lead": "Diverse navi cisterna sono state colpite nelle acque al largo degli Emirati Arabi Uniti e dello Yemen, con incendi segnalati su tre imbarcazioni, mentre droni sono stati intercettati nei pressi di Riyadh. Secondo l'agenzia britannica UKMTO, una nave cisterna GNL è stata attaccata da persone a bordo di un gommone al largo della città yemenita di Al Mukalla, mentre un rimorchiatore ha subito danni e un ferito lieve dopo essere stato colpito da due proiettili non identificati al largo di Khor Fakkan, negli Emirati. Nel contesto si segnalano anche attacchi di coloni mascherati contro politici europei in Cisgiordania occupata.",
   "more": [
    "Le tensioni nel Golfo e nel Mar Rosso si inseriscono in un contesto regionale segnato dal conflitto in corso tra Israele e i gruppi alleati dell'Iran, tra cui i ribelli Houthi in Yemen, che negli ultimi anni hanno colpito ripetutamente il traffico marittimo commerciale in risposta alla guerra a Gaza e alle tensioni con Teheran."
   ],
