   "titolo": "Arizona si unisce al Nevada contro i tagli alle quote d'acqua del fiume Colorado",
   "orig": "Arizona joins Nevada to fight proposed cuts to their shares of Colorado River",
   "lead": "L'Arizona si è unita al Nevada nella battaglia legale contro l'amministrazione Trump riguardo ai tagli proposti alle quote d'acqua del fiume Colorado, risorsa in forte contrazione. La mossa arriva dopo che il dipartimento dell'Interno ha annunciato in estate restrizioni che potrebbero ridurre drasticamente la fornitura d'acqua agli stati del bacino inferiore del fiume - Arizona, California e Nevada - nei prossimi due anni, in base alle condizioni del corso d'acqua. Lo riferisce The Guardian.",
   "more": [
    "Il fiume Colorado, fonte vitale per circa 40 milioni di persone in sette stati americani e in Messico, è sottoposto a crescente stress idrico per siccità prolungata e sovra-sfruttamento. Le dispute legali tra gli stati del bacino riflettono la difficoltà di gestire una risorsa sempre più scarsa in un contesto di cambiamento climatico."
   ],
