   "sez": "economia",
   "titolo": "Pensioni, la Cassazione cambia le regole su Quota 100: niente restituzione di un anno di assegni",
   "orig": "Pensioni, la Cassazione ora cambia Quota 100: stop alla restituzione di un anno di assegni, cosa dice la sentenza",
   "lead": "La Corte di Cassazione ha stabilito un nuovo principio riguardante Quota 100, la misura di prepensionamento: chi ha svolto un'attività lavorativa di pochi giorni, anche per poche centinaia di euro, in violazione del divieto di cumulo previsto dalla misura, non dovrà restituire un'intera annualità di pensione. La sentenza chiarisce che la perdita dell'intero assegno annuale sarebbe sproporzionata rispetto a violazioni minime. La decisione riguarda chi ha ottenuto il prepensionamento tramite Quota 100 e nel periodo interessato ha avuto un'attività lavorativa continuativa in violazione delle clausole della misura.",
   "more": [
    "Quota 100 era una misura di pensionamento anticipato introdotta nel 2019 in Italia, che permetteva di andare in pensione con almeno 62 anni di età e 38 di contributi, a condizione di non svolgere attività lavorativa. La Cassazione interviene ora per mitigare le sanzioni previste per chi non ha rispettato pienamente tale divieto."
   ],
