   "id": "zc84eb041",
   "sez": "spazio",
   "titolo": "Scoperta una stella verde a 280 anni luce dalla Terra",
   "orig": "Astronomers discover green star 280 light-years away; what makes it glow green",
   "lead": "Un gruppo di astronomi ha scoperto una nana bianca insolita, denominata WD J1330+6435, situata nella costellazione del Draco a circa 280 anni luce dalla Terra. La stella presenta una caratteristica tonalità verde dovuta all'interazione tra particelle di sodio ed elio nella sua atmosfera. Con una temperatura superficiale vicina ai 4.000 gradi Celsius, le sue dimensioni sono paragonabili a quelle del nostro pianeta. Lo riferisce Times of India.",
   "more": [
    "Le nane bianche sono i resti collassati di stelle simili al Sole giunte alla fine della loro vita. La loro colorazione dipende dalla composizione chimica degli strati atmosferici superficiali: in questo caso l'insolita combinazione di sodio ed elio produce l'effetto visivo verdastro, un fenomeno raro tra questi corpi celesti."
   ],
