   "sez": "salute",
   "titolo": "Nuovo scanner PET total-body produce immagini diagnostiche in appena un minuto",
   "orig": "Next-generation total-body PET scanner can produce diagnostic-quality images in as little as 1 minute",
   "lead": "Uno scanner PET/CT total-body di nuova generazione è in grado di produrre immagini di qualità diagnostica in appena un minuto di scansione, secondo una ricerca presentata al 39° Congresso annuale dell'Associazione Europea di Medicina Nucleare (EANM'26). Anche le immagini ottenute con i tempi di scansione più rapidi sono state valutate in media più positivamente rispetto a quelle prodotte da uno scanner PET/CT standard. Lo riferisce Medical Xpress.",
   "more": [
    "Gli scanner PET total-body rappresentano un'evoluzione rispetto ai tradizionali apparecchi PET, permettendo di visualizzare simultaneamente tutto il corpo con minore esposizione a radiazioni e tempi più brevi. Questa tecnologia può migliorare l'accesso agli esami diagnostici e il confort dei pazienti, specialmente nelle diagnosi oncologiche e nel monitoraggio delle terapie."
   ],
