   "id": "zc55d9287",
   "sez": "ambiente",
   "titolo": "Clima, spopolamento e isolamento sociale: i rischi futuri per le aree interne del Mezzogiorno",
   "orig": "Clima, spopolamento e isolamento sociale: i rischi del futuro per le aree interne del Mezzogiorno",
   "lead": "Il cambiamento climatico rappresenta una nuova emergenza per le aree interne del Mezzogiorno italiano, che si sommano a spopolamento e isolamento sociale già esistenti. Secondo Luca Bianchi, dell'istituto Svimez, il fenomeno climatico potrebbe costare fino a 6 punti di Pil entro il 2050, con il Sud Italia come area più esposta del Paese. Siccità e ondate di calore prolungate stanno già danneggiando il settore agroalimentare meridionale e le relative esportazioni. Lo riferisce Il Fatto Quotidiano.",
   "more": [
    "Le aree interne del Mezzogiorno soffrono da decenni di spopolamento legato alla mancanza di servizi e opportunità lavorative. Il cambiamento climatico rischia di aggravare questa tendenza, colpendo un'agricoltura già fragile e accelerando l'abbandono dei territori, con conseguenze sociali ed economiche destinate a pesare sull'intero Paese."
   ],
