   "orig": "Kaiju Decode: The Ring of Aidara Anime Film Releases Teaser Trailer, New Key Visual",
   "lead": "Tsuburaya Productions e Toei Animation hanno diffuso il primo teaser trailer e una nuova key visual del film anime 'Kaiju Decode: The Ring of Aidara', co-prodotto dalle due aziende giapponesi. La pellicola, che unisce l'eredità dei kaiju di Tsuburaya all'animazione di Toei, è prevista nelle sale per il 2027. Non sono ancora stati diffusi dettagli sulla trama o sul cast di doppiatori coinvolti nel progetto. Lo riferisce Crunchyroll News.",
