   "lead": "Il festival cinematografico filippino CinePanalo, organizzato da Puregold, sta selezionando opere locali capaci di far ridere, commuovere e riflettere il pubblico, puntando in particolare su storie raramente portate sullo schermo. L'iniziativa, con sede a Manila, mira a valorizzare la produzione cinematografica nazionale attraverso un approccio che privilegia l'originalità narrativa rispetto alle formule già consolidate. Lo riferisce Rappler.",
