   "id": "z58fd1669",
   "sez": "spazio",
   "titolo": "Il colore delle stelle dipende anche dalla densità, non solo dalla temperatura",
   "orig": "Di che colore sono le stelle?",
   "lead": "Nuove osservazioni indicano che il colore delle nane bianche, i resti di antichi pianeti e stelle, non dipende soltanto dalla temperatura, come si credeva finora, ma anche dalla densità della stella. Questo porterebbe alla formazione di colorazioni mai osservate prima in questo tipo di corpi celesti. La scoperta aggiorna le conoscenze sui processi fisici che determinano l'aspetto delle stelle morenti. Lo riferisce Focus.",
   "more": [
    "Le nane bianche sono i resti collassati di stelle simili al Sole giunte alla fine della loro vita; il loro colore viene tradizionalmente usato dagli astronomi per stimarne l'età e la temperatura superficiale."
   ],
