   "titolo": "Simulazioni studiano l'uso di armi nucleari per deviare asteroidi pericolosi",
   "orig": "Simulations explore nuclear mitigation of asteroid threats",
   "lead": "Ricercatori del Lawrence Livermore National Laboratory stanno sviluppando simulazioni tridimensionali per studiare come un dispositivo nucleare potrebbe essere impiegato per deviare o distruggere un asteroide in rotta di collisione con la Terra. Lo studio rientra negli sforzi scientifici per valutare strategie di difesa planetaria contro minacce provenienti da corpi celesti. Lo riferisce Phys.org.",
   "more": [
    "La difesa planetaria dagli asteroidi è un campo di ricerca che include anche missioni reali come DART della NASA, che nel 2022 ha testato con successo la deviazione cinetica di un asteroide; l'opzione nucleare resta uno scenario di riserva per minacce di grandi dimensioni."
   ],
