   "sez": "salute",
   "titolo": "Le cuffie antirumore in sala operatoria riducono la nausea post-chirurgica",
   "orig": "Wearing headphones during surgery may reduce nausea and vomiting afterward",
   "lead": "Uno studio clinico randomizzato presentato al meeting annuale Anesthesiology 2026 ha rilevato che i pazienti sottoposti a interventi di chirurgia ginecologica mininvasiva che indossavano cuffie con cancellazione del rumore durante l'operazione hanno avuto una probabilità significativamente minore di soffrire di nausea e vomito post-operatori rispetto a chi non le indossava. Lo riferisce Medical Xpress.",
   "more": [
    "La nausea e il vomito post-operatori sono effetti collaterali comuni degli interventi chirurgici sotto anestesia; i ricercatori indagano da tempo fattori ambientali, come rumore e stress sensoriale in sala operatoria, che potrebbero influenzarne l'insorgenza."
   ],
