   "lead": "La 1ª Vara Federale di Porto Alegre ha ordinato a Meta di ripristinare entro due giorni gli account Instagram di entità studentesche del Rio Grande do Sul, bloccati il 6 ottobre senza preavviso né motivazione. Tra le pagine sospese figurano quelle del Centro Acadêmico André da Rocha, del servizio di assistenza legale universitaria e di un direttorio accademico di economia. Le organizzazioni avevano denunciato il blocco simultaneo come ingiustificato. Lo riferisce Agência Brasil.",
