   "sez": "economia",
   "titolo": "Il contante torna protagonista nell'India digitale",
   "orig": "‘Cash is making a comeback’ in digital India",
   "lead": "In India, dove i pagamenti digitali tramite il sistema UPI si sono diffusi enormemente, il contante sta tornando in auge. L'economia sommersa alimenta la domanda di denaro fisico, mentre una nuova tassa potrebbe ridurre la popolarità dell'interfaccia digitale UPI. Il fenomeno rivela una tendenza inattesa in uno dei mercati dei pagamenti digitali più avanzati al mondo. Lo riferisce Financial Times.",
   "more": [
    "L'UPI (Unified Payments Interface) è il sistema di pagamento istantaneo indiano che ha rivoluzionato le transazioni digitali nel paese, rendendo l'India uno dei mercati leader mondiali nei pagamenti mobili negli ultimi anni."
   ],
