   "sez": "spazio",
   "titolo": "I droni intercettori ucraini perdono il segnale Starlink oltre i 161 km/h",
   "orig": "Ucraina, i droni si «spengono» dopo i 161 km/h: così Starlink «stacca» la connessione e gli intercettori non funzionano",
   "lead": "I droni intercettori ucraini impiegati contro i velivoli russi perdono la connessione con il sistema satellitare Starlink quando superano i 161 chilometri orari. Questo limite tecnico rischia di compromettere l'efficacia dei droni nel contrastare gli apparecchi russi, che sono invece più rapidi. Il problema evidenzia le difficoltà tecnologiche dell'Ucraina nella guerra dei droni contro Mosca. Lo riferisce Il Messaggero.",
   "more": [
    "Starlink, il servizio satellitare di SpaceX, è diventato uno strumento chiave per le comunicazioni militari ucraine durante il conflitto con la Russia, ma limiti tecnici come questo mostrano le sfide nell'adattare tecnologie civili a scopi bellici ad alta velocità."
   ],
