   "lead": "La Roma di Gianpiero Gasperini ha battuto 2-0 il Genoa guidato da Daniele De Rossi, lasciandosi alle spalle la sconfitta contro il Real Madrid. A segno Castro e Lulli, in una partita che per l'allenatore giallorosso rappresenta la 300ª panchina importante in carriera. Gasperini ha commentato la reazione della squadra, inclusi i giovani, e ha espresso la speranza di poter contare su Paulo Dybala nella prossima trasferta di Napoli. Lo riferisce Il Messaggero.",
