   "id": "zb1a11a6a",
   "sez": "prima",
   "titolo": "Negli USA le proteste \"No Kings\" spingono al voto anticipato per le elezioni di metà mandato",
   "orig": "'No Kings' rallies push early voting ahead of US midterm elections",
   "lead": "Gli organizzatori delle manifestazioni \"No Kings\", note per la loro impronta anti-Trump, hanno invitato gli americani a votare in anticipo in vista delle elezioni di metà mandato del 3 novembre. Migliaia di persone si sono riunite in eventi in tutto il paese sabato, proseguendo una serie di mobilitazioni iniziata quasi due anni fa. Gli eventi sono stati presentati come apartitici, ma puntano a consolidare il malcontento verso la presidenza Trump mentre i repubblicani affrontano sfide difficili per mantenere il controllo del Congresso.",
   "more": [
    "Le elezioni di metà mandato (midterm) statunitensi rinnovano l'intero Congresso e parte del Senato, senza eleggere il presidente. Il movimento \"No Kings\" è nato come protesta contro politiche ritenute autoritarie dell'amministrazione Trump, organizzando manifestazioni periodiche in tutto il paese dal 2024."
   ],
