   "id": "z87d6d961",
   "sez": "prima",
   "titolo": "Papa Leone XIV lascia il Gemelli, idoneo per il viaggio in Sud America",
   "orig": "Il Papa lascia il policlinico Gemelli",
   "lead": "Papa Leone XIV ha lasciato il policlinico Gemelli di Roma quattro giorni dopo l'intervento al polmone destro, rassicurando i fedeli sul proprio stato di salute. I medici lo hanno giudicato idoneo alle dimissioni e il Pontefice ha presieduto l'Angelus affacciato su piazza San Pietro. Il chirurgo che lo ha operato, Stefano Margaritora, ha confermato che non vi sono motivi clinici per rinunciare al previsto viaggio in America Latina. Lo riferisce Rai News.",
   "more": [
    "Il Policlinico Gemelli di Roma è storicamente l'ospedale di riferimento per la cura dei pontefici, già teatro dei ricoveri di Giovanni Paolo II e Francesco. Leone XIV, succeduto a Francesco nel 2025, ha subito un intervento per la rimozione di un adenocarcinoma polmonare."
   ],
